for(const drift of ['identity alias','restriction row','entry revision'])test('detached source metadata rejects '+drift+' before any newly requested body or label',async()=>{
 const f=await fixture();let handle,touches=0;try{({detached:handle}=await sourceDetached(f));await f.s.repository.transaction(true,async t=>{if(drift==='identity alias'){const row=await t.get('topics',f.parent.id);row.identity.aliases.push({token:'a'.repeat(64),actor:'user',revision:1,operationId:op(),at:'2026-10-19T00:00:00.000Z'});await rawPut(t,'topics',row);}else if(drift==='restriction row')await rawPut(t,'meta',{id:'topicKeepSeparate:'+op(),sourceId:f.parent.id,targetId:f.parent.id,revision:1,actor:'user',scope:'identity'});else{const row=await t.get('thoughts',f.entryIds[0]);row.revision++;await rawPut(t,'thoughts',row);}});const workBudget=createContextScopeWorkBudget({database:f.s.repository.db});await assert.rejects(f.s.repository.transaction(false,t=>{const get=t.get.bind(t),all=t.all.bind(t),protect=(table,row)=>{if(!row)return row;for(const field of {thoughts:['thoughtText','title','note'],topics:['name','nameKey','summary'],sections:['title']}[table]||[])Object.defineProperty(row,field,{enumerable:true,configurable:true,get(){touches++;throw Error('ungranted field');}});return row;};t.get=async(table,...args)=>protect(table,await get(table,...args));t.all=async(table,...args)=>(await all(table,...args)).map(row=>protect(table,row));return planMaintenanceSectionPromotionConfirmation(f.s,t,handle,{workBudget});}));assert.equal(touches,0);assert.equal(f.assessments,1);}finally{releaseMaintenanceDetachedSectionPromotion(handle);await f.close();}
});

