test('original child prepare waits outside the Store queue and captures only the granted complete Section',async()=>{
 const f=await fixture();let owner;try{const lease=await f.owner();owner=tasksFor(f,lease);const task=owner.begin(lease.plan,f.binding,{qualification:lease.qualification,signal:lease.signal.signal}),payload=await owner.ready(task);assert.equal(payload.sectionRef,'s0');assert.equal(payload.view.manifest.count,2);assert.equal(f.assessments,0);let entered=false;await f.s.run(()=>f.s.repository.transaction(false,async t=>{entered=true;assert.ok(await t.get('topics',f.parent.id));}));assert.equal(entered,true);owner.release(task);await assert.rejects(owner.ready(task));assert.equal((await rows(f.s,'topics')).length,1);}finally{owner?.dispose();await f.close();}
});
