for(const phase of ['confirm','stage'])for(const change of ['Source','identity'])test('strict '+phase+' rejects '+change+' changed after its original work put',async()=>{
 const f=await fixture();let restore;try{const lease=await f.owner(),preview=await lease.service.prepare(f.request),work=phase==='stage'?await lease.service.confirm(preview,{confirmed:true}):null,before=await snapshot(f.s),beforeWork=await rows(f.s,'organizerWorkItems'),transaction=f.s.repository.transaction.bind(f.s.repository);let injected=0;
 f.s.repository.transaction=(write,fn,...args)=>transaction(write,async t=>{if(write){const put=t.put.bind(t);t.put=async(table,row,...rest)=>{const result=await put(table,row,...rest);if(!injected&&table==='organizerWorkItems'&&row.kind==='personal_topic_promotion'){injected++;if(change==='identity')lease.identitySignal.abort();else{const source=(await t.all('records'))[0];source.value.originalText+=' SYNTHETIC post-work source drift';await put('records',source);}}return result;};}return fn(t);},...args);restore=()=>f.s.repository.transaction=transaction;
 await assert.rejects(phase==='confirm'?lease.service.confirm(preview,{confirmed:true}):lease.service.stage(work.workId));assert.equal(injected,1);assert.deepEqual(await snapshot(f.s),before);assert.deepEqual(await rows(f.s,'organizerWorkItems'),beforeWork);
 }finally{restore?.();await f.close();}
});

