 const f=await fixture();let restore;try{const old=await f.owner(),preview=await old.service.prepare(f.request),work=await old.service.confirm(preview,{confirmed:true}),before=await rows(f.s,'organizerWorkItems'),transaction=f.s.repository.transaction.bind(f.s.repository);let injected=0;f.s.repository.transaction=(write,fn,...args)=>transaction(write,async t=>{if(write){const put=t.put.bind(t);t.put=async(table,row,...rest)=>{const result=await put(table,row,...rest);if(!injected&&table==='organizerWorkItems'&&row.kind==='personal_topic_promotion'){injected++;const source=(await t.all('records'))[0];source.value.originalText+=' post-stage source';await put('records',source);}return result;};}return fn(t);},...args);restore=()=>f.s.repository.transaction=transaction;await assert.rejects(old.service.stage(work.workId));assert.equal(injected,1);assert.deepEqual(await rows(f.s,'organizerWorkItems'),before);restore();old.release();const fresh=await f.owner({assessor:false});await fresh.service.stage(work.workId);const result=await fresh.service.activate(work.workId);assert.equal(result.operationId,f.request.operationId);assert.equal(f.assessments,1);}finally{restore?.();await f.close();}
