// These mutations happen after the original domain callback has returned. Raw
// IDB writes avoid changing backupChanged, so only the frozen terminal plan can
// reject them. They do not substitute a generation mismatch for evidence CAS.
for(const phase of ['confirm','stage'])for(const change of ['Source','work intent','identity'])test('strict '+phase+' terminal rejects '+change+' after the original callback without a generation marker',async()=>{
 const f=await fixture(),transaction=f.s.repository.transaction.bind(f.s.repository);let injected=0;
 try{const lease=await f.owner(),preview=await lease.service.prepare(f.request),work=phase==='stage'?await lease.service.confirm(preview,{confirmed:true}):null,before=await snapshot(f.s),beforeWork=await rows(f.s,'organizerWorkItems');
  f.s.repository.transaction=(write,fn,...args)=>transaction(write,async t=>{const result=await fn(t);if(write&&!injected&&result?.workId==='personal-topic-promotion:'+f.request.operationId){injected++;if(change==='identity')lease.identitySignal.abort();else{const table=change==='Source'?'records':'organizerWorkItems',row=change==='Source'?(await t.all(table))[0]:await t.get(table,result.workId);if(change==='Source')row.value.originalText+=' SYNTHETIC after callback';else row.offset++;await new Promise((resolve,reject)=>{const put=t.tx.objectStore(table).put(row);put.onsuccess=()=>resolve();put.onerror=()=>reject(put.error);});}}return result;},...args);
  await assert.rejects(phase==='confirm'?lease.service.confirm(preview,{confirmed:true}):lease.service.stage(work.workId));assert.equal(injected,1);f.s.repository.transaction=transaction;assert.deepEqual(await snapshot(f.s),before);assert.deepEqual(await rows(f.s,'organizerWorkItems'),beforeWork);
 }finally{f.s.repository.transaction=transaction;await f.close();}
});

